import assert from 'node:assert';
import fs from 'node:fs';
import fsPromises from 'node:fs/promises';
import path from 'node:path';
import createDebug from 'debug';
import { glob, isDynamicPattern } from 'tinyglobby';
import normalize from 'normalize-path';
import File from 'vinyl';
import multimatch from 'multimatch';
import { resolveFromPaths, getCommonPath, globify, resolveGlobOptions, } from '../util.js';
import { writeInternal } from './write.js';
const debug = createDebug('mem-fs-editor:copy-async');
async function getOneFile(filepath) {
    const resolved = path.resolve(filepath);
    try {
        const stats = await fsPromises.stat(resolved);
        return stats.isFile() ? resolved : undefined;
    }
    catch {
        return undefined;
    }
}
const defaultFileTransform = ({ destinationPath, contents, }) => ({
    path: destinationPath,
    contents,
});
async function copySingleAsync(editor, from, to, options = {}) {
    const resolvedFrom = path.resolve(from);
    debug('Copying %s to %s with %o', resolvedFrom, to, options);
    const file = editor.store.get(resolvedFrom);
    assert.ok(file.contents, `Cannot copy empty file ${resolvedFrom}`);
    const { fileTransform = defaultFileTransform, transformOptions, transformData, } = options;
    const { path: destinationPath, contents } = await fileTransform({
        destinationPath: path.resolve(to),
        sourcePath: resolvedFrom,
        contents: file.contents,
        options: transformOptions,
        data: transformData,
    });
    if ((options.append ?? false) && editor.store.existsInMemory(destinationPath)) {
        editor.append(destinationPath, contents, { create: true, ...options });
    }
    else if (File.isVinyl(file)) {
        const clonedFile = file.clone({ contents: false, deep: false });
        writeInternal(editor.store, Object.assign(clonedFile, {
            contents: Buffer.from(contents),
            path: destinationPath,
            editorMetadata: options.metadata ?? clonedFile.editorMetadata,
        }));
    }
    else {
        writeInternal(editor.store, new File({
            contents: Buffer.from(contents),
            stat: fs.statSync(file.path, { throwIfNoEntry: false }),
            path: destinationPath,
            history: [file.path],
            editorMetadata: options.metadata,
        }));
    }
}
export async function copyAsync(from, to, options = {}) {
    const resolvedTo = path.resolve(to);
    const { noGlob = false } = options;
    const hasGlobOptions = Boolean(options.globOptions);
    const hasMultimatchOptions = Boolean(options.storeMatchOptions);
    assert.ok(!noGlob || !hasGlobOptions, '`noGlob` and `globOptions` are mutually exclusive');
    assert.ok(!noGlob || !hasMultimatchOptions, '`noGlob` and `storeMatchOptions` are mutually exclusive');
    if (typeof from === 'string') {
        const oneFile = await getOneFile(from);
        if (oneFile != null) {
            return copySingleAsync(this, oneFile, resolvedTo, options);
        }
    }
    const { fromBasePath = getCommonPath(from) } = options;
    const resolvedFromPaths = resolveFromPaths({ from, fromBasePath });
    const hasDynamicPattern = resolvedFromPaths.some((f) => isDynamicPattern(normalize(f.from)));
    const { preferFiles } = resolveGlobOptions({
        noGlob,
        hasDynamicPattern,
    });
    const storeFiles = [];
    const globResolved = [];
    for (const resolvedFromPath of resolvedFromPaths) {
        const { resolvedFrom } = resolvedFromPath;
        if (this.exists(resolvedFrom)) {
            storeFiles.push(resolvedFrom);
        }
        else {
            globResolved.push(resolvedFromPath);
        }
    }
    let diskFiles = [];
    if (globResolved.length > 0) {
        const patterns = globResolved.flatMap((file) => globify(file.from));
        const globMatches = await glob(patterns, {
            cwd: fromBasePath,
            ...options.globOptions,
            absolute: true,
            onlyFiles: true,
        });
        diskFiles = globMatches.map((file) => path.resolve(file));
        const normalizedStoreFilePaths = this.store
            .all()
            .filter((file) => this.exists(file.path))
            .map((file) => file.path)
            .filter((filePath) => !diskFiles.includes(filePath))
            .map((filePath) => normalize(filePath))
            // The store may have a glob path and when we try to copy it will fail because not real file
            .filter((filePath) => !isDynamicPattern(filePath));
        for (const filePath of multimatch(normalizedStoreFilePaths, patterns.map((p) => path.isAbsolute(p) ? p : path.posix.join(normalize(fromBasePath), p)), options.storeMatchOptions)) {
            storeFiles.push(path.resolve(filePath));
        }
    }
    // Sanity checks: Makes sure we copy at least one file.
    assert.ok((options.ignoreNoMatch ?? false) || diskFiles.length > 0 || storeFiles.length > 0, `Trying to copy from a source that does not exist: ${String(from)}`);
    // If `from` is an array, or if it contains any dynamic patterns, or if it doesn't exist, `to` must be a directory.
    const treatToAsDir = Array.isArray(from) || !preferFiles || globResolved.length > 0;
    let generateDestination = () => resolvedTo;
    if (treatToAsDir) {
        assert.ok(!this.exists(resolvedTo) || fs.statSync(resolvedTo).isDirectory(), 'When copying multiple files, provide a directory as destination');
        generateDestination = (filepath) => path.join(resolvedTo, path.relative(fromBasePath, filepath));
    }
    await Promise.all([
        ...diskFiles.map((file) => copySingleAsync(this, file, generateDestination(file), options)),
        ...storeFiles.map((file) => copySingleAsync(this, file, generateDestination(file), options)),
    ]);
}
